// RoomAsset.swift — PRTS Arknights base-room renders (fetched from prts.wiki
// furniture data, quantized, base64-embedded). Used as screensaver backdrops.

import CoreGraphics
import Foundation
import ImageIO

enum RoomAsset {
    static let names = ["天镜阁会客堂", "龙门食坊", "莱塔尼亚之夜", "汐斯塔沙滩小屋", "哥伦比亚咖啡馆", "兰赛拉尔宴会厅"]
    nonisolated(unsafe) static let images: [CGImage] = b64s.compactMap(decode)
    static var count: Int { images.count }

    private static func decode(_ s: String) -> CGImage? {
        guard let d = Data(base64Encoded: s),
              let src = CGImageSourceCreateWithData(d as CFData, nil),
              let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
        return img
    }

